def runway(buffer: float, income: float, spending: float) -> float | str:
    """Challenge formula: buffer check first, then shortfall, capped at 120."""
    gap = spending - income
    if buffer <= 0:
        return 0
    if gap <= 0:
        return NO_SHORTFALL
    return min(buffer / gap, 120)


